package org.botai.back.b2b;

import java.nio.charset.StandardCharsets;
import java.util.*;
import org.botai.back.catalog.TaskSnapshot;
import org.botai.back.common.JsonCodec;
import org.botai.back.expert.ExpertReviewDocument;
import org.botai.back.grading.port.GradingGateway;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;
import static org.assertj.core.api.Assertions.*;

/**
 * Frozen AI checkpoint 4565127952edbb86262ad43d94d7dccab26e7ca9, generated by its
 * tests/test_v2_artifacts.py::source/response fixture functions and validated by
 * the same AI module. Rejection uses its exact null-transition test. No provider,
 * HTTP model call, runtime school assignment, or rewritten proposed-wire fixture.
 */
class AcceptedAiFixtureTest {
    private final JsonCodec json=new JsonCodec(JsonMapper.builder().build());
    private final B2bAiResponseValidator validator=new B2bAiResponseValidator(json,new ExpertReviewDocument(json));
    private String fixture(String name)throws Exception{try(var stream=getClass().getResourceAsStream("/b2b/ai-456512-"+name+".json")){byte[] bytes=Objects.requireNonNull(stream).readAllBytes();String expected=name.equals("geometry")?"a9373848e45fcad2172641ab6674547a9e18de896b7a8cab807e298d0c3a5aff":"013abd8e2ab7eb6864c2edc3698a5608752a01e3243d26f323dbd955e734ab22";assertThat(java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes))).as("immutable fixture bytes: "+name).isEqualTo(expected);return new String(bytes,StandardCharsets.UTF_8);}}
    private B2bAiResponseValidator.Parsed parse(String raw)throws Exception{JsonNode root=json.read(raw),task=root.get("task");UUID id=UUID.fromString(task.get("id").asText());var snapshot=new TaskSnapshot(id,id,task.get("task_number").asInt(),task.get("max_score").asInt(),task.get("statement").asText(),task.get("reference_answer").asText(),null,List.of(),false);byte[] source;try(var stream=getClass().getResourceAsStream("/b2b/ai-456512-source.png")){source=Objects.requireNonNull(stream).readAllBytes();assertThat(java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(source))).isEqualTo("8fa9c3a98e9de6c9b3c6c64c8de555b92ec9b627ec794802c913b5f6f9f4c871");}var images=List.of(new GradingGateway.Image(UUID.fromString(root.get("solution_image_ids").get(0).asText()),source,"image/png"));return validator.parse(new GradingGateway.Response(raw,"mock","accepted-fixture",null),snapshot,images,"accepted-fixture","mock",false);}
    @Test void actualAiGeometryPenaltyAndCausalityAdaptWithoutDroppingStepMeaning()throws Exception{String raw=fixture("geometry");var parsed=parse(raw);UUID issued=UUID.randomUUID();var result=validator.adapt(parsed,d->{assertThat(d.source().toString()).isEqualTo("00000000-0000-4000-8000-000000000001");assertThat(d.crop().x()).isEqualTo(0.25);return issued;});var doc=json.read(json.write(result.feedback()));assertThat(doc.path("origin").asText()).isEqualTo("structured_ai");var blocks=doc.path("ocr").path("blocks");assertThat(blocks).hasSize(2);assertThat(blocks.get(0).path("title").asText()).isEqualTo("Чертёж и вычисление");assertThat(blocks.get(0).path("content").path("lines").get(0).asText()).isEqualTo("$AB=4$");assertThat(blocks.get(0).path("content").path("image").path("artifact_id").asText()).isEqualTo(issued.toString());assertThat(doc.path("analysis").path("findings").get(0).path("penalty").asInt()).isEqualTo(1);assertThat(doc.path("analysis").path("block_reviews").get(1).path("follows_from_block_ids").get(0).asText()).isEqualTo("s1");assertThat(result.score()).isEqualTo(2);assertThat(doc.toString()).doesNotContain("reference_answer","source_image_id","object_key");}
    @Test void actualAiRejectionStaysNullAndHasNoInventedScoreOrArtifacts()throws Exception{var parsed=parse(fixture("rejected"));var result=validator.adapt(parsed,d->{throw new AssertionError("Rejected response cannot create a crop");});var doc=json.read(json.write(result.feedback()));assertThat(result.graded()).isFalse();assertThat(result.score()).isNull();assertThat(doc.path("phase").asText()).isEqualTo("rejected");for(String key:List.of("ocr","analysis","grading"))assertThat(doc.get(key).isNull()).isTrue();assertThat(parsed.diagrams()).isEmpty();}
}
